'use strict';
const ICONS={today:'<rect x="3" y="4" width="18" height="17" rx="3"/><path d="M8 2v4m8-4v4M3 10h18m-13 5 3 3 5-5"/>',plan:'<path d="M8 5h13M8 12h13M8 19h13M3 5h.01M3 12h.01M3 19h.01"/>',courses:'<path d="M3 4h6a4 4 0 0 1 3 2 4 4 0 0 1 3-2h6v15h-6a4 4 0 0 0-3 2 4 4 0 0 0-3-2H3zM12 6v15"/>',library:'<rect x="3" y="3" width="4" height="18" rx="1"/><rect x="10" y="3" width="4" height="18" rx="1"/><path d="m17 4 4-1 3 17-4 1z"/>',activity:'<path d="M3 12h4l3-8 4 16 3-8h4"/>',boards:'<path d="M8 21V11H3v10m5 0h8V3H8v8m8 10h5V8h-5"/>',settings:'<path d="M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z"/><path d="m9 3-1 3-3 1-2 4 2 3v4l4 3 3-1 3 1 4-3v-4l2-3-2-4-3-1-1-3z"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',external:'<path d="M14 3h7v7m0-7L10 14M10 3H4v17h17v-6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',play:'<path d="m8 4 12 8-12 8z"/>',pause:'<path d="M8 4v16M16 4v16"/>',check:'<path d="m5 12 4 4L19 6"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',plus:'<path d="M12 4v16M4 12h16"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',refresh:'<path d="M20 8a8 8 0 1 0 0 8M20 3v5h-5"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v2m0 18v2M1 12h2m18 0h2M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M3 16v5h18v-5"/>'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${ICONS[name]||ICONS.grid}</svg>`;
const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='dima.identity.prototype.v1';
const TASKS=[{id:'pm1',title:'Explore the project life cycle',course:'Google Project Management',module:'Foundations · Sample lesson',time:25,type:'Reading',color:'blue'},{id:'pm2',title:'Map a project from start to finish',course:'Google Project Management',module:'Foundations · Sample practice',time:30,type:'Practice',color:'blue'},{id:'cs1',title:'Understand how computers represent information',course:'CS50 Business',module:'Computational thinking · Sample lesson',time:30,type:'Video',color:'orange'},{id:'cs2',title:'Reflect on technology in your business',course:'CS50 Business',module:'Computational thinking · Sample practice',time:20,type:'Reflection',color:'orange'}];
const fresh=()=>({done:[],theme:'light',privateCourses:[],sessions:[],recovered:null,plan:null,public:false,publication:'Not requested',timer:null});
let state=fresh(),storageAvailable=true;try{const stored=JSON.parse(localStorage.getItem(KEY));if(stored&&Array.isArray(stored.done)&&Array.isArray(stored.sessions)&&Array.isArray(stored.privateCourses))state={...fresh(),...stored}}catch{storageAvailable=false}
let view='today',course='pm',detailTab='outline',board='hours',boardFilter='All',query='',recoveryRevision=null;let revision=0;
const navs=[['today','Today','today'],['plan','My Plan','plan'],['courses','My Courses','courses'],['library','Library','library'],['activity','Activity','activity'],['boards','Leaderboards','boards']];
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));storageAvailable=true}catch{storageAvailable=false}const s=$('#save-status');if(s)s.textContent=storageAvailable?'This device only':'Not saved · storage unavailable'}
function announce(message,undo){const el=$('#toast');if(!el)return;el.innerHTML=`${esc(message)}${undo?'<button id="undo-action">Undo</button>':''}`;el.classList.add('visible');if(undo)$('#undo-action').onclick=()=>{undo();el.classList.remove('visible')};clearTimeout(announce.timeout);announce.timeout=setTimeout(()=>el.classList.remove('visible'),6500)}
function applyTheme(){document.documentElement.dataset.theme=state.theme}
function hydrateIcons(){document.querySelectorAll('[data-icon]').forEach(el=>{if(!el.querySelector('svg'))el.insertAdjacentHTML('afterbegin',icon(el.dataset.icon))})}
function nav(){const activeView=({detail:'courses',editor:'courses',setup:'plan',recovery:'plan'})[view]||view;const desktop=$('#desktop-nav');if(!desktop)return;desktop.innerHTML=navs.map(([id,label,i])=>`<button class="nav-item ${activeView===id?'active':''}" data-view="${id}" ${activeView===id?'aria-current="page"':''}>${icon(i)}${label}</button>`).join('');$('#mobile-nav').innerHTML=[['today','Today','today'],['plan','Plan','plan'],['courses','Courses','courses'],['more','More','more']].map(([id,label,i])=>`<button data-view="${id}" class="${activeView===id||(id==='more'&&!['today','plan','courses'].includes(activeView))?'active':''}" ${activeView===id?'aria-current="page"':''}>${icon(i)}${label}</button>`).join('');$('#breadcrumb').textContent=names[view]||'Today';hydrateIcons()}
const names={today:'Today',plan:'My Plan',courses:'My Courses',library:'Library',activity:'Activity',boards:'Leaderboards',settings:'Settings',more:'More',recovery:'Recovery preview',setup:'Build your plan',editor:'Create a course',detail:'Course detail'};
const button=(text,action,cls='')=>`<button class="button ${cls}" data-action="${action}">${text}</button>`;
const heading=(title,desc,action='')=>`<div class="page-header"><div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;
const progress=(ids)=>Math.round(ids.filter(x=>state.done.includes(x)).length/ids.length*100);
function taskRow(t){const done=state.done.includes(t.id);return `<li class="task-row ${done?'done':''}"><button class="check-button" data-complete="${t.id}" aria-label="${done?'Reopen':'Complete'} ${esc(t.title)}" aria-pressed="${done}"><span class="check-box">${done?icon('check'):''}</span></button><div class="task-copy"><strong>${t.title}</strong><small><span class="course-marker ${t.color}"></span> ${t.course} · ${t.type}${done?' · Complete':''}</small></div><span class="task-duration">${t.time} min</span></li>`}
function summary(code,title,color=''){const ids=TASKS.filter(t=>t.id.startsWith(code)).map(t=>t.id),n=ids.filter(id=>state.done.includes(id)).length;return `<div class="course-summary"><strong>${title}</strong><div class="summary-line"><span>${n} of ${ids.length} sample tasks</span><span>${progress(ids)}%</span></div><div class="progress-track" aria-label="${title}: ${n} of ${ids.length} sample tasks complete"><span style="width:${progress(ids)}%;${color?'background:var(--orange)':''}"></span></div></div>`}
function today(){const next=TASKS.find(t=>!state.done.includes(t.id)),done=TASKS.filter(t=>state.done.includes(t.id)).length;return heading('Your next good step.','A little focus. A little further.',`<div class="date-label">Sample day<strong>Saturday, 31 Oct</strong></div>`)+(!state.recovered?`<div class="notice">${icon('info')}<p><strong>Your plan has room to adjust.</strong> One sample task carried over from yesterday.</p><button class="button small" data-view="recovery">Review plan ${icon('arrow')}</button></div>`:`<div class="notice"><p><strong>Revised plan applied on this device.</strong> ${state.recovered==='deadline'?'Your target stays the same.':'Your daily workload stays the same.'} Completed work is unchanged.</p><button class="button small" data-view="plan">View plan</button></div>`)+`<div class="today-grid"><div><section class="next-task"><svg class="next-path" viewBox="0 0 240 220" aria-hidden="true"><path d="M10 206 H66 Q84 206 84 188 V165 Q84 148 103 148 H133 Q151 148 151 129 V93 Q151 76 168 76 H190 Q207 76 207 59 V16"/></svg><div class="next-body"><div class="section-line"><h2>${next?'Your next step':'A little further today.'}</h2><span class="badge">${next?'Ready to start':'Sample agenda complete'}</span></div>${next?`<div class="course-meta"><span class="course-marker ${next.color}"></span>${next.course}<span>/</span>${next.module}</div><h3>${next.title}</h3><p>A focused ${next.time}-minute block to move your learning forward. The estimate is illustrative; take the time you need.</p><div class="task-meta"><span>${icon('clock')}${next.time} min estimate</span><span>${icon('courses')}${next.type}</span><span>Required · Demo</span></div><div class="actions"><button class="button primary" data-complete="${next.id}">${icon('check')} Mark complete</button><a class="button" href="${next.id.startsWith('pm')?'https://www.coursera.org/professional-certificates/google-project-management':'https://cs50.harvard.edu/business/'}" target="_blank" rel="noopener noreferrer">Open provider ${icon('external')}</a><button class="button quiet" data-action="start">${icon('play')} Focus</button></div>`:`<h3>You showed up.<br>Keep that with you.</h3><p>All four demonstration tasks are complete. Explore the library or revisit a task whenever you need.</p><div class="actions" style="margin-top:20px"><button class="button primary" data-view="library">Explore the library ${icon('arrow')}</button></div>`}</div><div class="next-bottom"><span>${icon('lock')} Your progress is private.</span><span>Saved on this device only</span></div></section><section><div class="section-line"><h2>Today's agenda</h2><span class="mini-note">${state.done.length} of 4 sample tasks complete</span></div><ul class="task-list">${TASKS.map(taskRow).join('')}</ul><p class="mini-note" style="margin-top:16px">Illustrative task titles and durations. This is not an audited provider outline.</p></section></div><aside class="today-aside"><section class="side-section completion-context"><h2>A little adds up.</h2><div class="completion-summary"><dima-progress value="${Math.round(done/TASKS.length*100)}" label="Sample task completion">${Math.round(done/TASKS.length*100)}%</dima-progress><div><strong>${done} of ${TASKS.length}</strong><span>sample tasks complete</span></div></div><p>Every checked task stays yours. Timer minutes are tracked separately.</p></section><section class="side-section"><h2>Your week has breathing room.</h2><div class="week-strip">${['M','T','W','T','F','S','S'].map((d,i)=>`<div class="day ${i===5?'current':i<3?'complete':i===6?'rest':''}">${d}<span>${26+i>31?1:26+i}</span></div>`).join('')}</div><p>Sunday is a rest day.<br>Your plan makes space for it.</p><button class="text-link" data-view="plan">See your week ${icon('arrow')}</button></section><section class="side-section"><h2>Steady, course by course.</h2>${summary('pm','Google Project Management')}${summary('cs','CS50 Business',true)}<button class="text-link" data-view="courses">My courses ${icon('arrow')}</button></section><section class="side-section"><h2>Progress has its own pace.</h2><p>Missed a day? Keep what you have done. Make a new plan for what comes next.</p><a class="text-link" href="landing.html">About ديمة ${icon('arrow')}</a></section></aside></div>`}
function plan(){const revised=state.recovered;return heading('Your week, with room to live.','One shared workload across your courses.',`<button class="button" data-view="setup">Adjust plan</button>`)+`<div class="notice"><p><strong>${state.plan?'Your local plan preferences are set.':'Sample plan · 26 October – 1 November'}</strong> ${state.plan?`${state.plan.minutes} minutes on ${state.plan.days.length} selected days. Target ${esc(state.plan.target)}.`:'Dates and workloads are illustrative, not your confirmed deadlines.'}</p></div><div class="two-col"><section><div class="section-line"><h2>26 Oct – 1 Nov</h2><span class="badge neutral">Sample week</span></div><ul class="week-list">${[['Mon','26 Oct','Explore the course structure','Complete · sample history'],['Tue','27 Oct','Set your learning intentions','Complete · sample history'],['Wed','28 Oct','Computational thinking','Sample history'],['Thu','29 Oct','No study recorded','Sample history'],['Fri','30 Oct','Map a project from start to finish',revised?'Moved to next week':'Carried over · 30 min'],['Sat','31 Oct','Explore the project life cycle','60 min · planned'],['Sun','1 Nov','Rest day','Protected']].map((r,i)=>`<li class="week-row ${i===5?'today':''}"><div><strong>${r[0]}</strong><small>${r[1]}</small></div><ul><li>${r[2]}</li>${i===5?'<li>Computers and information</li>':''}</ul><small>${r[3]}</small></li>`).join('')}</ul>${revised?`<div class="section-title"><h2>Next week · revised allocation</h2></div><p class="mini-note">Fixed demo recovery scenario. Saturday's 60-minute plan and completed history stay unchanged.</p><ul class="week-list" style="margin-top:16px">${revised==='deadline'?`<li class="week-row"><div><strong>Mon</strong><small>2 Nov</small></div><ul><li>Existing sample workload · 60 min</li><li>Project mapping · carried-over part 1 · 15 min</li></ul><small>75 min · revised</small></li><li class="week-row"><div><strong>Wed</strong><small>4 Nov</small></div><ul><li>Existing sample workload · 60 min</li><li>Project mapping · carried-over part 2 · 15 min</li></ul><small>75 min · revised</small></li>`:`<li class="week-row"><div><strong>Mon</strong><small>2 Nov</small></div><ul><li>Existing sample workload · 30 min</li><li>Project mapping · carried over · 30 min</li></ul><small>60 min · unchanged limit</small></li>`}<li class="week-row"><div><strong>Sun</strong><small>8 Nov</small></div><ul><li>Rest day</li></ul><small>Protected</small></li></ul>`:''}</section><aside class="panel"><h2>Plans can change.</h2><p>Review unfinished work, compare your options, and decide what fits. Your completed work stays exactly where it belongs.</p><dl><div class="definition-row"><dt>Daily load in fixed recovery scenario</dt><dd>${revised==='deadline'?'60 min base; Mon/Wed 75 min':'60 min ceiling'}</dd></div><div class="definition-row"><dt>Sample target</dt><dd>${revised==='workload'?'7 Dec 2026':'30 Nov 2026'}</dd></div><div class="definition-row"><dt>Protected rest</dt><dd>Sunday</dd></div><div class="definition-row"><dt>Estimate confidence</dt><dd>Illustrative only</dd></div></dl><button class="button primary" data-view="recovery">Review recovery ${icon('arrow')}</button><p class="mini-note" style="margin-top:18px">This demonstration previews a fixed scenario. It does not calculate a complete course schedule.</p></aside></div>`}
function recovery(){recoveryRevision=revision;return heading('A fresh plan. Same progress.','Choose how to make room for the work that remains.')+`<div class="content-narrow"><div class="notice"><p><strong>Demo scenario:</strong> one unfinished 30-minute block. Completed tasks and Sunday rest stay untouched.</p></div><form id="recovery-form"><div class="recovery-options"><label class="option"><input type="radio" name="recovery" value="deadline" checked><strong>Keep my target date</strong><p>Add 15 minutes on Monday 2 November and Wednesday 4 November.</p><dl><div class="definition-row"><dt>Target</dt><dd>30 Nov → 30 Nov</dd></div><div class="definition-row"><dt>2 & 4 Nov load</dt><dd>60 → 75 min</dd></div><div class="definition-row"><dt>Moved block</dt><dd>Split: 15 + 15 min</dd></div></dl></label><label class="option"><input type="radio" name="recovery" value="workload"><strong>Keep my daily workload</strong><p>Use 30 minutes of open capacity on Monday 2 November and extend the target.</p><dl><div class="definition-row"><dt>Target</dt><dd>30 Nov → 7 Dec</dd></div><div class="definition-row"><dt>Daily load</dt><dd>60 min ceiling unchanged</dd></div><div class="definition-row"><dt>Moved block</dt><dd>Mon 2 Nov · 30 min</dd></div></dl></label></div><section class="panel"><h2>Only the future moves.</h2><p>Completed work, recorded time, and protected rest days remain unchanged. This local preview changes no course completion and awards no ranked credit.</p><dl><div class="definition-row"><dt>Completed sample tasks</dt><dd>${state.done.length} preserved</dd></div><div class="definition-row"><dt>Historical time</dt><dd>Unchanged</dd></div><div class="definition-row"><dt>Effect</dt><dd>Future demo allocation only</dd></div></dl></section><div class="actions" style="margin-top:24px"><button class="button primary" type="submit">Apply revised plan ${icon('check')}</button><button class="button" type="button" data-view="plan">Keep current plan</button></div></form></div>`}
function setup(){return heading('Make a plan that fits.','Start small. Your available time is shared across all courses.')+`<form id="setup-form" class="content-narrow panel"><h2>Your starting point</h2><div class="form-grid"><div class="field"><label for="plan-course">Course</label><select id="plan-course" name="course">${['Google Project Management','CS50 Business','Both sample courses'].map(name=>`<option ${name===state.plan?.course?'selected':''}>${name}</option>`).join('')}</select></div><div class="field"><label for="starting-point">Prior progress</label><select id="starting-point" name="prior"><option value="new" ${state.plan?.prior!=='existing'?'selected':''}>Start from the beginning</option><option value="existing" ${state.plan?.prior==='existing'?'selected':''}>I've already started — review later</option></select><small>No historical progress is imported automatically.</small></div><div class="field"><label for="target">Target finish date</label><input type="date" id="target" name="target" required value="${esc(state.plan?.target||'2026-11-30')}"><small>Example date. Replace it with your own target.</small></div><div class="field"><label for="minutes">Shared daily workload</label><select id="minutes" name="minutes">${[30,45,60,90].map(n=>`<option value="${n}" ${n===(state.plan?.minutes||60)?'selected':''}>${n} minutes</option>`).join('')}</select><small>Across all selected courses, not per course.</small></div></div><fieldset class="field"><legend>Study days</legend><div class="day-choices">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map((d,i)=>`<label class="day-choice"><input type="checkbox" name="days" value="${d}" ${state.plan?state.plan.days.includes(d)?'checked':'':i<6?'checked':''}><span>${d}</span></label>`).join('')}</div></fieldset><div class="notice"><p>These settings are stored locally. A full curriculum-based scheduling engine, feasibility validation, and prior-progress import are future implementation work.</p></div><div id="setup-error" role="alert"></div><div class="actions"><button class="button primary" type="submit">Use this demo plan ${icon('arrow')}</button><button class="button" type="button" data-view="today">Cancel</button></div></form>`}
function courseEntry(id,title,provider,library=false){const pm=id==='pm';return `<article class="course-entry"><div class="course-letter ${pm?'':'orange'}">${pm?'G':'H'}</div><div><h3>${title}</h3><p>${provider} · English · ${pm?'Seven-course program':'Standalone course'}</p>${library?'<span class="badge neutral">Seed offering · outline review pending</span>':`${summary(id,'Sample task progress',!pm)}`}</div><button class="button" data-course="${id}">View course ${icon('arrow')}</button></article>`}
function courses(){return heading('Keep your learning together.','Shared courses. A plan that is yours.',`<button class="button primary" data-view="editor">${icon('plus')} Add course</button>`)+courseEntry('pm','Google Project Management','Google · Coursera')+courseEntry('cs','CS50 Business','Harvard University')+state.privateCourses.map((c,i)=>`<article class="course-entry"><div class="course-letter">${icon('lock')}</div><div><h3>${esc(c.title)}</h3><p>${esc(c.provider||'Independent course')} · Private · ${c.tasks.length} outline items</p><span class="badge neutral">Local draft</span></div><button class="button" data-private="${i}">View outline ${icon('arrow')}</button></article>`).join('')+`<div class="publication"><h3>Your course, your choice.</h3><p>Private course outlines stay private. A future publication request shares only the reviewed outline, never personal learning records.</p><button class="text-link" data-view="editor">Create a private course ${icon('arrow')}</button></div>`}
function library(){const entries=[['pm','Google Project Management','Google · Coursera'],['cs','CS50 Business','Harvard University']].filter(x=>x.join(' ').toLowerCase().includes(query.toLowerCase()));return heading('Find your next direction.','Two seed offerings. Bring your own course whenever you need.')+`<form id="search-form" class="search-row"><div class="field"><label for="search">Search the library</label><input id="search" name="query" type="search" placeholder="Course or provider" value="${esc(query)}"></div><button class="button primary" type="submit">${icon('search')} Search</button>${query?button('Clear search','clear-search'):''}</form><p class="mini-note">${entries.length} offering${entries.length===1?'':'s'} · Provider-hosted learning · No enrollment or progress sync with providers</p>${entries.length?entries.map(x=>courseEntry(...x,true)).join(''):`<div class="empty-state">${icon('search')}<h2>No matching course yet.</h2><p>Your search stays here. You can create a private course with your own outline.</p><button class="button primary" data-view="editor">Add this course</button></div>`}`}
function detail(){const pm=course==='pm',title=pm?'Google Project Management':'CS50 Business',items=TASKS.filter(t=>t.id.startsWith(course));return `<button class="text-link" data-view="courses">My courses</button><div class="course-detail-header"><div class="course-letter ${pm?'':'orange'}">${pm?'G':'H'}</div><div><h1>${title}</h1><p>${pm?'Google · Coursera · Seven-course program':'Harvard University · Standalone course'} · English</p><p>Seed offering · Version for demonstration · Personal progress is user-reported</p></div></div><div class="actions"><button class="button primary" data-view="today">Continue learning ${icon('arrow')}</button><button class="button" data-view="setup">Adjust my plan</button><a class="button" href="${pm?'https://www.coursera.org/professional-certificates/google-project-management':'https://cs50.harvard.edu/business/'}" target="_blank" rel="noopener noreferrer">Provider source ${icon('external')}</a></div><div class="tabs" role="tablist" aria-label="Course sections">${['outline','progress','community'].map(t=>`<button role="tab" class="tab" id="course-tab-${t}" aria-controls="course-tab-panel" tabindex="${detailTab===t?0:-1}" data-detailtab="${t}" aria-selected="${detailTab===t}">${{outline:'Course outline',progress:'My progress',community:'Community & rules'}[t]}</button>`).join('')}</div><section id="course-tab-panel" role="tabpanel" aria-labelledby="course-tab-${detailTab}">${detailTab==='outline'?`<div class="notice"><p><strong>Sample outline, not a published curriculum.</strong> These two representative tasks demonstrate ordering and progress. Full required tasks, weights, and provider durations still need review.</p></div><details open><summary>${pm?'Foundations of Project Management':'Computational thinking'} <span class="badge neutral">Sample module</span></summary><ul class="task-list">${items.map(taskRow).join('')}</ul></details><details><summary>Supporting resources</summary><p class="mini-note">Open the provider source for official course information. Resources do not count as required completion credit.</p></details>`:detailTab==='progress'?`<div class="panel content-narrow"><h2>Your sample progress</h2>${summary(course,title,!pm)}<p style="margin-top:20px">This percentage covers only the two demonstration tasks shown here. It is not your provider progress or the official course completion percentage.</p><button class="text-link" data-view="activity">View recorded activity ${icon('arrow')}</button></div>`:`<div class="empty-state">${icon('boards')}<h2>Your learning is private.</h2><p>No classmates or rankings are simulated. Public membership and ranking participation are separate choices for a future connected service.</p><button class="button" data-action="course-board">View course board rules</button></div>`}</section>`}
function editor(){return heading('Give your course a place.','Create a private outline. Make it public only after review.')+`<form id="editor-form" class="content-narrow"><div class="panel"><h2>Course details</h2><div class="form-grid"><div class="field"><label for="course-title">Course title</label><input id="course-title" name="title" maxlength="160" required placeholder="e.g. Introduction to service design"></div><div class="field"><label for="provider">Provider or author <span class="mini-note">(optional)</span></label><input id="provider" name="provider" maxlength="160" placeholder="Who created the course?"></div><div class="field"><label for="source">Source URL <span class="mini-note">(optional)</span></label><input id="source" name="source" type="url" placeholder="https://"></div><div class="field"><label for="language">Language</label><select name="language" id="language"><option>English</option><option>Arabic</option><option>Other</option></select></div></div><div class="field"><label for="outline">Ordered outline</label><textarea id="outline" name="outline" required placeholder="One task or module per line&#10;Understand the basics&#10;Try a guided exercise&#10;Build a small project"></textarea><small>Lines retain their order. This coarse outline has no invented durations or competitive weights.</small></div><div class="actions"><button class="button primary" type="submit">${icon('lock')} Save private course</button><button class="button" type="button" data-action="preview-outline">Preview outline</button></div><div id="outline-preview" style="margin-top:20px"></div></div><section class="publication"><h3>Publication request</h3><p>Only the title, provider, source, language, and ordered outline would be shared. Progress, goals, and time remain private.</p><span class="badge neutral">${esc(state.publication)}</span><div style="margin-top:12px"><button class="button" type="button" data-action="publication">Prepare publication request draft</button></div><p class="mini-note">A local draft only. Nothing is sent, reviewed, or published.</p></section></form>`}
function activity(){return heading('The work you put in.','Time and task completion tell different parts of the story.',`<button class="button" data-action="manual">${icon('plus')} Add manual time</button>`)+`<div id="manual-form-slot"></div><div class="notice"><p><strong>Personal activity only.</strong> Local demo timers and manual entries do not earn ranked hours.</p></div><div class="section-line"><h2>On this device</h2><span class="mini-note">${state.sessions.length} session${state.sessions.length===1?'':'s'}</span></div>${state.sessions.length?state.sessions.slice().reverse().map(s=>`<article class="activity-row">${icon(s.manual?'plan':'clock')}<div><h3>${esc(s.type)} session</h3><p>${new Date(s.ended).toLocaleDateString('en-GB',{day:'numeric',month:'short'})} · ${s.manual?'Manual duration':'Local timer'} · Not ranked</p></div><span class="activity-duration">${Math.floor(s.seconds/60)}m ${s.seconds%60}s</span></article>`).join(''):`<div class="empty-state">${icon('clock')}<h2>Your next session starts here.</h2><p>Use the focus control below for Work or Learning. Completing a task never invents time spent.</p><button class="button primary" data-action="start">Start a focus session</button></div>`}<div class="section-title"><h2>Task completion</h2></div>${state.done.length?`<ul class="task-list">${TASKS.filter(t=>state.done.includes(t.id)).map(taskRow).join('')}</ul>`:'<p class="mini-note">No sample tasks completed yet. Your agenda is ready in Today.</p>'}`}
function boards(){return heading('Different effort. Different measures.','Choose a board, understand the rules, and participate on your terms.')+`<div class="tabs" role="tablist" aria-label="Ranking type"><button role="tab" class="tab" id="board-tab-hours" aria-controls="board-tab-panel" tabindex="${board==='hours'?0:-1}" data-board="hours" aria-selected="${board==='hours'}">Global hours</button><button role="tab" class="tab" id="board-tab-course" aria-controls="board-tab-panel" tabindex="${board==='course'?0:-1}" data-board="course" aria-selected="${board==='course'}">Course progress</button></div><section id="board-tab-panel" role="tabpanel" aria-labelledby="board-tab-${board}">${board==='hours'?`<div class="section-line"><h2>Eligible timer hours</h2><span class="badge neutral">This week · UTC</span></div><div class="actions" style="margin-bottom:24px">${['All','Learning','Work'].map(t=>`<button class="button ${boardFilter===t?'primary':''}" data-filter="${t}" aria-pressed="${boardFilter===t}">${t}</button>`).join('')}</div>`:`<div class="field" style="max-width:420px"><label for="board-course">Comparison scope</label><select id="board-course"><option>Google Project Management · Seed version</option><option>CS50 Business · Seed version</option></select></div><div class="section-line"><h2>Overall required progress</h2><span class="badge neutral">Percent of fixed course scope</span></div>`}<div class="empty-state">${icon('boards')}<h2>No eligible activity yet.</h2><p>This prototype has no connected community. There are no real ranks, simulated people, or fabricated scores.</p><button class="button" data-view="settings">Review privacy preferences</button></div><div class="section-title"><h2>How this board would work</h2></div><ul class="rules">${board==='hours'?`<li>Measure: finalized eligible timer duration, shown in hours and minutes. Work and Learning can be filtered separately.</li><li>Manual or edited duration remains in personal Activity; it is excluded from ranking.</li><li>Pauses are excluded. A four-hour continuous-interval cap is the proposed pilot recording rule, with review before resuming.</li><li>Local prototype sessions are not server-confirmed and are never presented as eligible.</li>`:`<li>Measure: completed required task weight ÷ the fixed published weight of the same course version. Required weights and denominator must be reviewed before a board opens.</li><li>Overall progress and new credited progress this week are separate measures. This prototype has no published denominator.</li><li>Prior progress belongs in overall completion, with no new weekly credit. Undo and recompletion cannot generate repeated weekly credit.</li><li>Optional work and resources do not add competitive weight. Timer hours do not increase course progress.</li>`}</ul></section>`}
function settings(){return heading('A space that stays yours.','Choose how it looks and what you would share.')+`<section class="content-narrow"><div class="settings-row"><div><h3>Dark appearance</h3><p>A quieter surface for evening sessions.</p></div><button class="switch" role="switch" aria-label="Dark appearance" aria-checked="${state.theme==='dark'}" data-action="theme"><span></span></button></div><div class="settings-row"><div><h3>Public leaderboard participation</h3><p>Local preference preview only. Your demo data is never published.</p></div><button class="switch" role="switch" aria-label="Public leaderboard participation preference" aria-checked="${state.public}" data-action="privacy"><span></span></button></div><div class="settings-row"><div><h3>Private by default</h3><p>Your plan, progress, notes, and time are personal. Course enrollment does not make them public.</p></div>${icon('lock')}</div><div class="settings-row"><div><h3>Export this demo</h3><p>Download only the local demonstration data as JSON.</p></div><button class="button" data-action="export">${icon('download')} Export</button></div><div class="settings-row"><div><h3>Start fresh</h3><p>Reset this prototype's sample tasks, courses, timers, and preferences.</p></div><button class="button danger" data-action="reset" aria-expanded="false" aria-controls="reset-confirmation">Reset demo</button></div><div id="reset-confirmation"></div><div class="publication"><h3>Design prototype, not a connected account.</h3><p>Changes stay in this browser's local storage. There is no sign-in, cross-device sync, provider integration, publication service, or production data.</p><div class="actions"><a class="button" href="components.html">Explore components</a><a class="button" href="landing.html">Public overview</a></div></div></section>`}
function more(){return heading('A little more room.','Everything else, within reach.')+`<div class="more-grid">${[['library','Library','library'],['activity','Activity','activity'],['boards','Leaderboards','boards'],['editor','Create a course','plus'],['setup','Plan setup','plan'],['settings','Settings','settings']].map(([id,label,i])=>`<button class="nav-item" data-view="${id}">${icon(i)}${label}${icon('arrow')}</button>`).join('')}<a class="nav-item" href="../studio.html">${icon('grid')}Component studio</a><a class="nav-item" href="landing.html">${icon('external')}Public overview</a></div>`}
function render(focus=false){if(!$('#main'))return;$('#main').dataset.currentView=view;$('#main').innerHTML=({today,plan,courses,library,activity,boards,settings,more,recovery,setup,editor,detail}[view]||today)();document.title=`${names[view]||'Today'} · ديمة`;nav();renderTimer();window.DimaUI?.init($('#main'));if(focus){$('#main').focus({preventScroll:true});window.scrollTo(0,0)}}
function navigate(id){view=id;location.hash=id;render(true)}
function elapsed(){if(!state.timer)return 0;return Math.floor((state.timer.elapsed+(state.timer.running?Math.min(Date.now()-state.timer.started,14400000):0))/1000)}
function renderTimer(){const rail=$('#session-rail');if(!rail)return;const t=state.timer;rail.innerHTML=t?`<div class="session-icon">${icon('clock')}</div><div class="session-copy"><strong>${t.type} · ${t.running?'In focus':'Paused'}</strong><small>Local demo timer · Not ranked</small></div><span class="timer-value" id="timer-value">${formatTime(elapsed())}</span><button class="button" data-action="${t.running?'pause':'resume'}" aria-label="${t.running?'Pause':'Resume'} session">${icon(t.running?'pause':'play')}<span>${t.running?'Pause':'Resume'}</span></button><button class="button primary" data-action="finish">Finish</button>`:`<div class="session-icon">${icon('play')}</div><div class="session-copy"><strong>A little focus goes a long way.</strong><small>Start a session when you're ready. Time and progress stay separate.</small></div><label class="sr-only" for="session-type">Session type</label><select id="session-type"><option>Learning</option><option>Work</option></select><button class="button primary" data-action="start">${icon('play')} Start session</button>`}
function formatTime(s){return [Math.floor(s/3600),Math.floor(s%3600/60),s%60].map(n=>String(n).padStart(2,'0')).join(':')}
function complete(id){if(!TASKS.some(t=>t.id===id))return;const wasDone=state.done.includes(id);state.done=wasDone?state.done.filter(x=>x!==id):[...state.done,id];revision++;persist();render();announce(wasDone?'Task reopened on this device.':'Task complete on this device. No time added.',()=>{state.done=wasDone?[...new Set([...state.done,id])]:state.done.filter(x=>x!==id);revision++;persist();render()})}
function startTimer(){if(state.timer){announce('One session is already active. Resume or finish it below.');return}state.timer={type:$('#session-type')?.value||'Learning',running:true,started:Date.now(),elapsed:0};persist();renderTimer();announce('Local timer started. No ranked hours are awarded.')}
function pauseTimer(){if(!state.timer?.running)return;state.timer.elapsed+=Math.min(Date.now()-state.timer.started,14400000);state.timer.running=false;persist();renderTimer()}
function finishTimer(){if(!state.timer)return;const seconds=elapsed();state.sessions.push({type:state.timer.type,seconds,ended:Date.now(),manual:false});state.timer=null;persist();render();announce('Session saved on this device. Task completion is unchanged.')}
function resetDemo(){const slot=$('#reset-confirmation');if(!slot)return;slot.innerHTML=`<section class="panel" role="region" aria-labelledby="reset-title" style="margin:0 0 22px"><h2 id="reset-title">Reset only this demo?</h2><p id="reset-description">This removes Dima's local sample progress, private courses, sessions, and preferences. Other browser data is not changed. This cannot be undone.</p><div class="actions" style="margin-top:18px"><button class="button" data-action="reset-cancel" aria-describedby="reset-description">Cancel</button><button class="button danger" data-action="reset-confirm" aria-describedby="reset-description">Reset demo data</button></div></section>`;$('[data-action="reset"]').setAttribute('aria-expanded','true');$('[data-action="reset-cancel"]').focus()}
function cancelDemoReset(){const slot=$('#reset-confirmation');if(slot)slot.innerHTML='';const trigger=$('[data-action="reset"]');if(trigger){trigger.setAttribute('aria-expanded','false');trigger.focus()}}
function confirmDemoReset(){if(!$('[data-action="reset-confirm"]'))return;state=fresh();revision++;persist();applyTheme();navigate('today');announce('Demo reset. Other browser data was not changed.')}
document.addEventListener('click',e=>{const navEl=e.target.closest('[data-view]');if(navEl){navigate(navEl.dataset.view);return}const task=e.target.closest('[data-complete]');if(task){complete(task.dataset.complete);return}const c=e.target.closest('[data-course]');if(c){course=c.dataset.course;detailTab='outline';navigate('detail');return}const p=e.target.closest('[data-private]');if(p){const item=state.privateCourses[Number(p.dataset.private)];$('#main').innerHTML=heading(esc(item.title),'Private course · Local outline only',`<button class="button" data-view="courses">Back to courses</button>`)+`<div class="panel content-narrow"><p>${esc(item.provider||'Independent course')} · ${esc(item.language)}</p><ol class="outline-preview">${item.tasks.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><span class="badge neutral">Coarse outline · No published ranking weights</span></div>`;return}const dt=e.target.closest('[data-detailtab]');if(dt){detailTab=dt.dataset.detailtab;render();return}const b=e.target.closest('[data-board]');if(b){board=b.dataset.board;render();return}const f=e.target.closest('[data-filter]');if(f){boardFilter=f.dataset.filter;render();return}const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;switch(action){case'commands':openWorkspaceCommands(e.target.closest('button'));break;case'start':startTimer();break;case'pause':pauseTimer();break;case'resume':if(state.timer&&!state.timer.running){state.timer.started=Date.now();state.timer.running=true;persist();renderTimer()}break;case'finish':finishTimer();break;case'theme':state.theme=state.theme==='dark'?'light':'dark';persist();applyTheme();render();break;case'privacy':state.public=!state.public;persist();render();announce('Local preference changed. No data was published.');break;case'reset':resetDemo();break;case'reset-cancel':cancelDemoReset();break;case'reset-confirm':confirmDemoReset();break;case'clear-search':query='';render();break;case'course-board':board='course';navigate('boards');break;case'preview-outline':{const value=$('#outline').value.trim();$('#outline-preview').innerHTML=value?`<h3>Ordered outline preview</h3><ol class="outline-preview">${value.split('\n').filter(x=>x.trim()).map(t=>`<li>${esc(t)}</li>`).join('')}</ol>`:'<p class="error-message" role="alert">Add at least one outline item to preview your course.</p>';break}case'publication':state.publication='Draft prepared · Not submitted';persist();e.target.closest('.publication').querySelector('.badge').textContent=state.publication;announce('Publication request draft prepared locally. Nothing was sent.');break;case'manual':$('#manual-form-slot').innerHTML=`<form id="manual-form" class="panel" style="margin-bottom:24px"><h2>Add personal time</h2><div class="form-grid"><div class="field"><label for="manual-type">Activity</label><select name="type" id="manual-type"><option>Learning</option><option>Work</option></select></div><div class="field"><label for="manual-minutes">Duration in minutes</label><input id="manual-minutes" name="minutes" type="number" required min="1" max="1440" value="30"></div></div><p class="mini-note">Manual duration is personal history. It never contributes to the hours board.</p><button class="button primary" style="margin-top:16px">Save manual entry</button></form>`;$('#manual-minutes').focus();break;case'export':{const blob=new Blob([JSON.stringify({prototype:'Dima identity demo',...state},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='dima-demo-data.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);announce('Local demo export downloaded.');break}}});
document.addEventListener('submit',e=>{const form=e.target;if(!['recovery-form','setup-form','editor-form','search-form','manual-form'].includes(form.id))return;e.preventDefault();const data=new FormData(form);if(form.id==='search-form'){query=data.get('query').trim();render();return}if(form.id==='recovery-form'){if(recoveryRevision!==revision){announce('Progress changed. Review this fresh preview before applying.');render();return}state.recovered=data.get('recovery');persist();navigate('plan');announce('Future demo plan revised. Completed history preserved.');return}if(form.id==='setup-form'){const days=data.getAll('days');if(!days.length){$('#setup-error').innerHTML='<p class="error-message">Choose at least one study day to continue.</p>';return}state.plan={course:data.get('course'),target:data.get('target'),minutes:Number(data.get('minutes')),days,prior:data.get('prior')};persist();navigate('plan');announce('Plan preferences saved locally. Full scheduling is not implemented.');return}if(form.id==='editor-form'){const title=data.get('title').trim(),tasks=data.get('outline').split('\n').map(x=>x.trim()).filter(Boolean);if(!title||!tasks.length){announce('Add a course title and at least one outline item.');return}const source=data.get('source');if(source&&!/^https?:\/\//i.test(source)){announce('Use an http or https source URL. Your draft is still here.');return}state.privateCourses.push({title,provider:data.get('provider').trim(),source,language:data.get('language'),tasks});persist();navigate('courses');announce('Private course saved on this device. Nothing was published.');return}if(form.id==='manual-form'){state.sessions.push({type:data.get('type'),seconds:Number(data.get('minutes'))*60,ended:Date.now(),manual:true});persist();render();announce('Manual time saved locally. Excluded from rankings.')}});
window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(names[id]&&id!==view){view=id;render(true)}});
window.addEventListener('storage',e=>{if(e.key!==KEY||!e.newValue)return;try{const incoming=JSON.parse(e.newValue);if(Array.isArray(incoming.done)){state={...fresh(),...incoming};revision++;applyTheme();render();announce('Demo updated from another tab on this device.')}}catch{}});
applyTheme();hydrateIcons();if($('#main')){view=names[location.hash.slice(1)]?location.hash.slice(1):'today';render();if(!storageAvailable)announce('Browser storage is unavailable. Changes last for this open page only.');setInterval(()=>{if(state.timer?.running&&Date.now()-state.timer.started>=14400000){pauseTimer();announce('Four-hour demo interval cap reached. Review and resume when ready.')}const display=$('#timer-value');if(display)display.textContent=formatTime(elapsed())},1000)}

// Native tab semantics plus arrow-key navigation for both app tab sets.
document.addEventListener('keydown',e=>{const tab=e.target.closest('[data-detailtab],[data-board]');if(!tab||!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;const tabs=[...tab.parentElement.querySelectorAll('[role=tab]')],i=tabs.indexOf(tab);const n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:tabs.length-1))%tabs.length;const attr=tabs[n].hasAttribute('data-detailtab')?'data-detailtab':'data-board',value=tabs[n].getAttribute(attr);e.preventDefault();tabs[n].click();document.querySelector(`[${attr}="${value}"]`)?.focus()});

document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#reset-confirmation')?.contains(e.target)&&$('[data-action="reset-confirm"]')){e.preventDefault();cancelDemoReset()}});

// Dima-native command interaction, adapted through ../ui/ from the 21st command palette.
// Reference: https://21st.dev/@rafa-porto/components/command-palette
function workspaceCommands(){return [
  {label:'Today',description:'Your next step and sample agenda',href:'#today'},
  {label:'My Plan',description:'Weekly workload and protected rest',href:'#plan'},
  {label:'Review recovery',description:'Compare options before changing your future plan',href:'#recovery'},
  {label:'Build your plan',description:'Course, target date and available study days',href:'#setup'},
  {label:'My Courses',description:'Your sample courses and private local outlines',href:'#courses'},
  {label:'Course library',description:'Explore the two starter courses',href:'#library'},
  {label:'Create a course',description:'Build a private outline on this device',href:'#editor'},
  {label:'Activity',description:'Session history and personal time entries',href:'#activity'},
  {label:'Leaderboards',description:'Preview ranking rules and honest empty states',href:'#boards'},
  {label:'Settings',description:'Theme, local privacy preference and data export',href:'#settings'},
  {label:'Component studio',description:'Explore reusable Dima interactions',href:'../studio.html'},
  {label:'About Dima',description:'The public product overview',href:'landing.html'}
]}
function openWorkspaceCommands(trigger){
  if(window.DimaUI?.openCommands)window.DimaUI.openCommands(workspaceCommands(),trigger||$('#command-trigger'));
  else{navigate('more');announce('Quick search is unavailable. All workspace pages are available here.')}
}
document.addEventListener('keydown',e=>{
  if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){
    e.preventDefault();
    if(!document.querySelector('dialog[open]'))openWorkspaceCommands($('#command-trigger'));
  }
});
